    Gets the sum of all numbers up to the provided number.
    E.g. gaussian_sum(5) == sum([1, 2, 3, 4, 5])
    :param number:
    :return:
    """
def gaussian_sum(number: int) -> int {
    return ((number * (1 + number)) // 2);
}

